// دریافت متن خام
const inputData = $input.first().json;
let rawText = inputData.output || inputData.text || inputData.message?.content || "";

if (typeof rawText !== 'string') {
  rawText = JSON.stringify(rawText);
}

rawText = rawText.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();

// پیدا کردن محدوده JSON
const startIdx = rawText.indexOf('{');
const endIdx = rawText.lastIndexOf('}');
let jsonStr = (startIdx !== -1 && endIdx !== -1) ? rawText.substring(startIdx, endIdx + 1) : rawText;

// اصلاح کامای فارسی
jsonStr = jsonStr.replace(/،/g, ',');

// تابع هوشمند برای اصلاح خودکار و ۱۰۰٪ سالم‌سازی آدرس عکس‌ها
function sanitizeHtmlImages(htmlContent) {
  if (!htmlContent) return "";
  return htmlContent.replace(/<img[^>]+src=['"]([^'"]+)['"]/gi, (match, src) => {
    let cleanSrc = src.trim();
    // افزودن https اگر فراموش شده باشد
    if (!cleanSrc.startsWith('http://') && !cleanSrc.startsWith('https://')) {
      cleanSrc = 'https://' + cleanSrc.replace(/^\/+/, '');
    }
    // جایگزینی فاصله با خط تیره
    cleanSrc = cleanSrc.replace(/\s+/g, '-');
    // حذف حروف فارسی احتمالی از آدرس
    cleanSrc = cleanSrc.replace(/[\u0600-\u06FF]+/g, 'image');
    return match.replace(src, cleanSrc);
  });
}

// تلاش برای پارس
try {
  const sanitized = jsonStr.replace(/[\r\n\t]/g, " ");
  const parsed = JSON.parse(sanitized);
  if (parsed.content) parsed.content = sanitizeHtmlImages(parsed.content);
  return [{ json: parsed }];
} catch (e1) {
  // استخراج دستی مقاوم
  try {
    const extractValue = (key) => {
      const match = jsonStr.match(new RegExp(`"${key}"\\s*:\\s*"([\\s\\S]*?)"\\s*[,}]`, 'i'));
      return match ? match[1] : "";
    };

    let title = extractValue("title");
    let excerpt = extractValue("excerpt");
    let category = extractValue("category");
    let content = "";

    const contentMatch = jsonStr.match(/"content"\s*:\s*"([\s\S]*)/i);
    if (contentMatch) {
      content = contentMatch[1].replace(/"\s*}\s*$/, '').trim();
      if (content.endsWith('"')) content = content.slice(0, -1);
    }

    content = sanitizeHtmlImages(content);

    if (title || content) {
      return [{
        json: {
          title: title.replace(/\\"/g, '"').trim(),
          excerpt: excerpt.replace(/\\"/g, '"').trim(),
          category: category.replace(/\\"/g, '"').trim(),
          content: content.replace(/\\"/g, '"').replace(/[\r\n\t]+/g, " ").trim()
        }
      }];
    }
  } catch (e2) {
    console.error("Extraction error:", e2);
  }

  return [{ json: { error: "پارس JSON ناموفق بود.", raw: rawText } }];
}
